INSERT INTO "post" ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019cfd70-4dea-7635-a535-12acfcf3db85','note','published','public',NULL,1773778521,'What I Actually Use My Notebook For',NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I always imagine I will use a fresh notebook for my best thoughts. In reality, it becomes useful much sooner and in messier ways."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Mostly three things"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Shopping lists"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fragments I do not trust my phone with"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The first ugly version of an idea"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"That turns out to be enough. A notebook does not need to become an archive. It only needs to catch the thought before it slips away."}]}]}','<p>I always imagine I will use a fresh notebook for my best thoughts. In reality, it becomes useful much sooner and in messier ways.</p><h2>Mostly three things</h2><ol><li><p>Shopping lists</p></li><li><p>Fragments I do not trust my phone with</p></li><li><p>The first ugly version of an idea</p></li></ol><p>That turns out to be enough. A notebook does not need to become an archive. It only needs to catch the thought before it slips away.</p>','I always imagine I will use a fresh notebook for my best thoughts. In reality, it becomes useful much sooner and in messier ways. Mostly three things Shopping lists Fragments I do not trust my phone with The first ugly version of an idea That turns out to be enough. A notebook does not need to become an archive. It only needs to catch the thought before it slips away.',NULL,'I always imagine I will use a fresh notebook for my best thoughts. In reality, it becomes useful much sooner and in messier ways.
