INSERT INTO "post" ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019cfd70-6bdf-7321-baf2-c18502a64a7b','quote','published','public',NULL,NULL,'From Epictetus','https://en.wikiquote.org/wiki/Epictetus','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A little stern, maybe. Still useful on the mornings when I drift too long before starting anything."}]}]}','<p>A little stern, maybe. Still useful on the mornings when I drift too long before starting anything.</p>','A little stern, maybe. Still useful on the mornings when I drift too long before starting anything.','First say to yourself what you would be; and then do what you have to do.',NULL,NULL,NULL,'019cfd70-6bdf-7321-baf2-c18502a64a7b',NULL,1770274500,1770274500,1773778529,1773778529);
INSERT INTO "post" ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019cfd70-6fbe-7442-bd09-725c9b9b97d8','note','published','public',NULL,1773778530,'Rain Makes My Neighborhood Look Better',NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything sharpens after a light shower: the crosswalk paint, the leaves stuck to the curb, the bakery sign that usually disappears into the block."}]},{"type":"paragraph","content":[{"type":"text","text":"I took the long way home for no reason other than the street looked newly washed. That was reason enough."}]}]}','<p>Everything sharpens after a light shower: the crosswalk paint, the leaves stuck to the curb, the bakery sign that usually disappears into the block.</p><p>I took the long way home for no reason other than the street looked newly washed. That was reason enough.</p>','Everything sharpens after a light shower: the crosswalk paint, the leaves stuck to the curb, the bakery sign that usually disappears into the block. I took the long way home for no reason other than the street looked newly washed. That was reason enough.',NULL,'Everything sharpens after a light shower: the crosswalk paint, the leaves stuck to the curb, the bakery sign that usually disappears into the block.
